#!/usr/bin/env node
/**
 * Install the shipped subset of the approved identity into `apps/web/public/brand/`.
 *
 * The design system lives in `docs/brand/logo-system/stack-family/` and is generated by
 * `docs/brand/logo-system/build_stack_identity.cjs`. The app ships only the handful of
 * files it actually references — the rest of the family (masters, proofs, the personalised
 * poster edition, the photographic heroes) stays in the design system.
 *
 * This script exists so the shipped assets have a traceable origin. Both directories are
 * committed: `docs/brand/` went into git on 10 Sep (`fb6ecbd`), and since Batch U3 the
 * third-party stills and posters in it are untracked and ignored (`OWNER-ACTIONS.md` 15,
 * `DECISIONS.md` #221). The generator's inputs are all still tracked.
 *
 *   node scripts/brand-sync.mjs           copy the manifest into apps/web/public/brand
 *   node scripts/brand-sync.mjs --check   report drift; exit 1 if anything differs
 *
 * The web tests run the same comparison as `--check` in CI, over every file in
 * `apps/web/public/brand/`, including the four photographic files shipped outside this
 * manifest (`brand-integration.test.ts`).
 */

import { createHash } from 'node:crypto'
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const SOURCE = join(ROOT, 'docs/brand/logo-system/stack-family')
const TARGET = join(ROOT, 'apps/web/public/brand')

/**
 * Every file the web app is allowed to reference, with the surface that references it.
 * Adding a row here is the only way a new brand asset reaches the bundle.
 */
const MANIFEST = [
  // Platform icons — concept-art emblem, the approved artwork at 192 px and above.
  ['favicon.ico', 'browser tab, 16/32/48 px'],
  ['apple-touch-icon.png', 'iOS add-to-home-screen, 180 px'],
  ['app-icon-concept-art-192.png', 'web manifest icon'],
  ['app-icon-concept-art-384.png', 'web manifest icon'],
  ['app-icon-concept-art-512.png', 'web manifest icon, push notification icon'],
  ['app-icon-concept-art-maskable-192.png', 'web manifest maskable icon'],
  ['app-icon-concept-art-maskable-512.png', 'web manifest maskable icon'],
  ['notification-badge-96.png', 'push notification badge — one-colour, alpha only'],
  ['social-card-1200x630.png', 'og:image / twitter:image'],

  // Interface marks — vector, theme-paired.
  ['stack-mark.svg', 'BrandMark >= 128 px, dark surfaces'],
  ['stack-mark-light.svg', 'BrandMark >= 128 px, light surfaces'],
  ['stack-mark-compact.svg', 'BrandMark 32-96 px, dark surfaces'],
  ['stack-mark-compact-light.svg', 'BrandMark 32-96 px, light surfaces'],
  ['micro-mark-16.svg', 'BrandMark < 32 px'],

  // Lockups — mark plus wordmark.
  ['horizontal-lockup-dark.svg', 'BrandLockup horizontal, dark surfaces'],
  ['horizontal-lockup-light.svg', 'BrandLockup horizontal, light surfaces'],
  ['stacked-lockup-dark.svg', 'BrandLockup stacked, dark surfaces'],
  ['stacked-lockup-light.svg', 'BrandLockup stacked, light surfaces'],
]

const digest = (buffer) => createHash('sha256').update(buffer).digest('hex').slice(0, 16)

function main() {
  const check = process.argv.includes('--check')

  if (!existsSync(SOURCE)) {
    console.error(`Design system not found at ${SOURCE}.`)
    console.error('It is tracked in git; see docs/brand-integration.md.')
    process.exit(2)
  }

  if (!check) mkdirSync(TARGET, { recursive: true })

  const drift = []
  for (const [name, usage] of MANIFEST) {
    const source = readFileSync(join(SOURCE, name))
    const destination = join(TARGET, name)
    const current = existsSync(destination) ? readFileSync(destination) : null

    if (current !== null && current.equals(source)) {
      if (check) console.log(`  ok       ${name}  ${digest(source)}  (${usage})`)
      continue
    }

    drift.push(name)
    if (check) {
      console.log(`  DRIFT    ${name}  ${current === null ? 'missing' : digest(current)} != ${digest(source)}`)
      continue
    }
    writeFileSync(destination, source)
    console.log(`  ${current === null ? 'added   ' : 'updated '} ${name}  ${digest(source)}`)
  }

  if (check && drift.length > 0) {
    console.error(`\n${drift.length} shipped asset(s) differ from the design system.`)
    console.error('Run `node scripts/brand-sync.mjs` to reinstall them.')
    process.exit(1)
  }
  console.log(check ? '\nShipped brand assets match the design system.' : `\n${MANIFEST.length} assets installed in apps/web/public/brand/.`)
}

main()
